import {ages,weights} from './data.js';
import {ketamineHeightChart} from './ketamine-height.js';
import {drugReference,categories} from './medication-data.js';
import {calculateDose,fmt,kgFrom,poundsFrom,orderedDose,dripRate,infusionRate,dilute,number} from './calculations.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const range=(low,high)=>low===high?fmt(low):`${fmt(low)}–${fmt(high)}`;
export const referenceUI={search:'',category:'',protocol:'',open:new Set()};
let concentrations={};try{concentrations=JSON.parse(sessionStorage.getItem('wfd-stock-v1')||'{}');}catch{}
export function setConcentration(id,value,custom=false){concentrations[id]=custom||value==='custom'?{custom:true,value:value==='custom'?'':value}:value;try{sessionStorage.setItem('wfd-stock-v1',JSON.stringify(concentrations));}catch{}}
const selectedStock=m=>concentrations[m.id]??'';
const stockConcentration=m=>{const saved=selectedStock(m);return m.stock?.concentration??number(saved?.custom?saved.value:saved);};
const input=(fields,key,label,placeholder='',extra='')=>`<label class="field">${label}<input id="${key}" data-ref-field="${key}" type="text" inputmode="decimal" value="${esc(fields[key]??'')}" placeholder="${esc(placeholder)}" ${extra}></label>`;
const select=(fields,key,label,options,defaultValue='')=>`<label class="field">${label}<select id="${key}" data-ref-field="${key}">${options.map(([value,label])=>`<option value="${esc(value)}" ${(fields[key]??defaultValue)===String(value)?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`;
const unitOptions=[['mg','mg'],['mcg','mcg'],['g','g'],['mEq','mEq']];
export const patientKg=fields=>kgFrom(fields['ref-weight'],fields['ref-weight-unit']??'kg');
function patientContext(fields,table=false,sedation=false){const kg=patientKg(fields),age=number(fields['ref-age']);return `<section class="panel reference-context"><div class="reference-fields">
  ${input(fields,'ref-age','Patient age · years','Enter age to check dose eligibility')}
  <div class="weight-entry">${input(fields,'ref-weight','Patient weight','Measured / validated weight')}${select(fields,'ref-weight-unit','Unit',[['kg','kg'],['lb','lb']],'kg')}</div>
  ${sedation?'':input(fields,'ref-ideal','Optional: for adult ketamine dosing','Ideal weight · kg')}
</div>${table?'<p class="calculator-note age-help">Age confirms adult / pediatric dose eligibility. For infants, enter years as a decimal (6 months = 0.5).</p>':''}${table&&age!==null&&age>=0&&age<16?`<div class="pediatric-table-picker">${select(fields,'ref-table','Pediatric table column',[['','Auto · exact table weight'],...ages.map((label,i)=>[String(i),label+' · '+weights[i]+' kg'])])}<p class="calculator-note">Table doses take precedence. No interpolation; missing entry: N/A.</p></div>`:''}${kg!==null?`<p class="weight-equivalent">${fmt(kg)} kg = ${fmt(poundsFrom(kg))} lb</p>`:''}</section>`;}
function recipeCard(m,p,r,ri,fields){
  const concentration=p.concentration??stockConcentration(m);
  const unit=p.concentrationUnit??m.stock?.unit;
  const priorKey=`prior-${p.id}-${ri}`;
  const result=calculateDose(r,{weightKg:patientKg(fields),idealKg:fields['ref-ideal'],age:fields['ref-age'],concentration,concentrationUnit:unit,prior:fields[priorKey],tableIndex:fields['ref-table']});
  const formula=r.kind==='weight'?`${range(r.low,r.high)} ${r.unit}/kg${r.ideal?' ideal weight':''}`:r.kind==='fixed'?`${range(r.low,r.high)} ${r.unit}`:r.rule==='glucagon-age'?'Age-based dose':'Weight-band dose';
  const perDose=m.id==='push-epi';
  const ceiling=r.max!==undefined?` · max ${fmt(r.max)} ${r.unit}`:'';
  return `<article class="dose-card" data-recipe="${p.id}-${ri}"><div class="dose-card-title"><b>${esc(r.label)}</b>${r.route?`<span class="route-pill">${esc(r.route)}</span>`:''}</div>
    ${r.blocked?'':result.table&&!perDose?'<p class="dose-formula">PEDIATRIC TABLE · App J</p>':`<p class="dose-formula">${esc(formula+ceiling)}${perDose?' per dose':''}${r.min!==undefined?` · min ${fmt(r.min)} ${esc(r.unit)}`:''}</p>`}
    ${r.totalMax!==undefined||r.totalPerKg!==undefined?`${input(fields,priorKey,`Already given · ${r.unit} (0 if none)`,'0')}<p class="dose-limit">Total maximum: ${r.totalPerKg?`${r.totalPerKg} ${r.unit}/kg`:`${r.totalMax} ${r.unit}`}</p>`:''}
    <div class="dose-output" aria-live="polite">${result.error?`<p class="calculation-empty">${esc(result.error)}</p>`:`<div><span>${result.table?'TABLE DOSE':'CALCULATED DOSE'}${perDose?' · PER DOSE':''}</span><strong>${range(result.low,result.high)} <small>${esc(result.unit)}</small></strong>${result.table?`<p>${esc(result.tableAge)} · ${result.tableWeight} kg reference</p>`:''}${result.weight?`<p>${fmt(result.weight)} kg${result.ideal?' ideal body weight':''}</p>`:''}</div>${r.unit==='unit'?'':`<div><span>${result.printedVolume?'TABLE VOLUME':r.unit==='mL'?'SOLUTION VOLUME':'DRAW FROM STOCK'}</span><strong><span>${result.volumeLow===null?'—':range(result.volumeLow,result.volumeHigh)}</span> <small>mL</small></strong><p>${result.volumeLow===null?'Confirm concentration above.':r.unit==='mL'?'Use specified solution.':`${fmt(concentration)} ${esc(unit)}/mL${p.concentration?' · pathway-specific stock':''}`}</p></div>`}${result.limited?'<p class="dose-limit">Protocol dose limit applied.</p>':''}${result.remaining!==null?`<p class="dose-limit">Remaining cumulative allowance: ${fmt(result.remaining)} ${esc(r.unit)}.</p>`:''}${r.prime&&result.volumeLow!==null?`<p class="dose-limit">Draw ${range(result.volumeLow+r.prime,result.volumeHigh+r.prime)} mL including ${r.prime} mL atomizer priming; dose volume above excludes priming.</p>`:''}`}</div>
  </article>`;
}
function stockControl(m){const s=m.stock;if(!s)return ''; if(s.confirmed)return `<div class="stock-summary ${m.id==='midazolam'?'stock-default':''}"><b>${esc(s.label)}</b><span>${s.unit==='mL'?'Specified solution':s.department||m.id==='ketamine'?'Department stock':'Protocol preparation'}</span></div>`;
  const saved=selectedStock(m),value=saved?.custom?saved.value:saved,custom=!!saved?.custom||value==='custom'||!!value&&!s.options.some(([n])=>Number(n)===Number(value));
  return `<div class="stock-control"><label class="field">${esc(s.label)}<select id="stock-${m.id}" data-stock="${m.id}"><option value="">Select / confirm concentration</option>${s.options.map(([n,label])=>`<option value="${n}" ${!custom&&String(value)===String(n)?'selected':''}>${esc(label)}</option>`).join('')}<option value="custom" ${custom?'selected':''}>Other concentration</option></select></label>${custom?`<label class="field">Product concentration · ${esc(s.unit)}/mL<input id="custom-${m.id}" data-stock-custom="${m.id}" type="text" value="${esc(value==='custom'?'':value)}" inputmode="decimal"></label>`:''}</div>`;
}
export function medicationReference(fields,source){
  const search=referenceUI.search.toLowerCase();
  const matches=drugReference.map(m=>{const nameMatch=m.name.toLowerCase().includes(search);const paths=m.pathways.filter(p=>(!referenceUI.protocol||p.code.split(' / ').includes(referenceUI.protocol))&&(!search||nameMatch||(p.title+' '+p.code+' '+p.recipes.map(r=>r.route??'').join(' ')).toLowerCase().includes(search)));return {m,paths};}).filter(({m,paths})=>paths.length&&(!referenceUI.category||m.category===referenceUI.category));
  const codes=[...new Set(drugReference.flatMap(m=>m.pathways.flatMap(p=>p.code.split(' / '))))].sort();
  return `<div class="page-heading"><div><div class="eyebrow">UNUSUAL DRUGS & TREATMENTS</div><h1>Unusual drugs</h1></div><button class="button primary" data-page="calculators">Dose & drip calculators ↗</button></div>
    <div class="reference-note">2026 Southwest Ohio · Verify indication, route, concentration, and required orders. ${source('FULL PROTOCOL',1)}</div>
    ${patientContext(fields,true)}
    <section class="reference-toolbar"><label class="search">Search<input id="reference-search" aria-label="Search medications or indications" placeholder="Medication, indication, protocol…" value="${esc(referenceUI.search)}"></label>
      <label class="field">Protocol<select id="reference-protocol"><option value="">All protocols</option>${codes.map(c=>`<option ${referenceUI.protocol===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>
      <label class="field">Category<select id="reference-category"><option value="">All categories</option>${categories.map(c=>`<option ${referenceUI.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>
    </section><p class="reference-count">${matches.length} drugs / treatments · expand an item, then its indication</p>
    <div class="drug-list">${matches.map(({m,paths},index)=>`${m.notCarried&&!matches[index-1]?.m.notCarried?'<div class="not-carried-heading"><h2>Not carried · may encounter</h2><p>Blood products, paralytics, and Cyanokit.</p></div>':''}<details class="drug-card ${m.color}${m.notCarried?' not-carried':''}" data-ref-open="drug-${m.id}" ${referenceUI.open.has('drug-'+m.id)?'open':''}><summary><span class="drug-marker">${esc(m.name[0])}</span><span class="drug-name"><b>${esc(m.name)}</b><small>${m.notCarried?'<span class="stock-status">Not carried · may encounter</span> · ':''}${esc(m.category)} · ${paths.length} ${paths.length===1?'indication':'indications'}</small></span><span class="expand-symbol" aria-hidden="true">+</span></summary>
      <div class="drug-content">${stockControl(m)}${m.preparation?`<section class="mixing-guide"><h2>MAKE 10 mcg/mL · final volume 10 mL</h2><ol>${m.preparation.map(step=>`<li>${esc(step)}</li>`).join('')}</ol>${source('MIXING · SB205',54)}</section>`:''}
      ${m.cautions?`<div class="med-cautions">${m.cautions.map(text=>`<p>${esc(text)}</p>`).join('')}</div>`:''}
      ${paths.map(p=>`<details class="protocol-path" data-ref-open="path-${p.id}" ${referenceUI.open.has('path-'+p.id)?'open':''}><summary><span><b>${esc(p.title)}</b><small>${esc(p.code)}</small></span><span class="expand-symbol" aria-hidden="true">+</span></summary><div class="path-content">
        <div class="path-protocols">${source('PROTOCOL · '+p.code,p.page)}${(p.refs??[]).map(ref=>source(...ref)).join('')}</div>
        ${p.stockLabel?`<div class="path-stock">${esc(p.stockLabel)}</div>`:''}
        ${p.notes.length?`<div class="path-notes">${p.notes.map(note=>`<p>${esc(note)}</p>`).join('')}</div>`:''}
        <div class="dose-grid">${p.recipes.map((r,ri)=>recipeCard(m,p,r,ri,fields)).join('')}</div>
      </div></details>`).join('')}</div>
    </details>`).join('')||'<div class="empty-state">No matching medication or pathway.</div>'}</div>`;
}
const resultBox=(values,empty='Enter valid values to calculate.')=>`<div class="utility-result" aria-live="polite">${values?values.map(([label,value,unit])=>`<div><span>${label}</span><strong>${esc(value)} <small>${unit}</small></strong></div>`).join(''):`<p>${empty}</p>`}</div>`;
export function calculators(fields,source){
  const kg=patientKg(fields),convert=kgFrom(fields['convert-value'],fields['convert-unit']??'lb');
  const ordered=orderedDose({dose:fields['calc-dose'],doseUnit:fields['calc-dose-unit']??'mg',perKg:fields['calc-basis']==='kg',weightKg:kg,max:fields['calc-max'],stockAmount:fields['calc-stock-amount'],stockUnit:fields['calc-stock-unit']??'mg',stockVolume:fields['calc-stock-volume']});
  const drip=dripRate(fields['drip-volume'],fields['drip-minutes'],fields['drip-factor']);
  const infusion=infusionRate({dose:fields['infusion-dose'],rateUnit:fields['infusion-unit']??'mcg/kg/min',weightKg:kg,stockAmount:fields['infusion-amount'],stockUnit:fields['infusion-stock-unit']??'mg',bagVolume:fields['infusion-volume'],factor:fields['infusion-factor']});
  const dilution=dilute({stockAmount:fields['dilution-amount'],stockUnit:fields['dilution-stock-unit']??'mg',stockVolume:fields['dilution-stock-volume'],targetConcentration:fields['dilution-target'],targetUnit:fields['dilution-target-unit']??'mcg',finalVolume:fields['dilution-final-volume']});
  return `<div class="page-heading"><div><div class="eyebrow">QUICK CALCULATORS</div><h1>Doses, drips & units</h1></div><button class="button primary" data-page="medications">Unusual drug protocols ↗</button></div>
  <div class="reference-note">Use the ordered dose and confirmed concentration. ${source('FULL PROTOCOL',1)}</div>${patientContext(fields)}
  <div class="calculator-grid">
    <section class="panel calculator"><h2>kg ↔ lb</h2><div class="calculator-fields">${input(fields,'convert-value','Weight','Value')}${select(fields,'convert-unit','From',[['lb','lb'],['kg','kg']],'lb')}</div>
      ${resultBox(convert!==null?[['KILOGRAMS',fmt(convert),'kg'],['POUNDS',fmt(poundsFrom(convert)),'lb']]:null)}<button class="button small" data-use-weight="convert">Use as patient weight</button><p class="calculator-note"><b>Enter pounds or kilograms to get the other unit. “Use as patient weight” copies the kilograms into the dose calculators.</b></p></section>
    <section class="panel calculator"><h2>Ordered dose → mL</h2><div class="calculator-fields">
      ${input(fields,'calc-dose','Ordered dose')}${select(fields,'calc-dose-unit','Dose unit',unitOptions,'mg')}${select(fields,'calc-basis','Dose basis',[['total','Total dose'],['kg','Per kg patient weight']],'total')}${input(fields,'calc-max','Maximum per dose · same unit','Optional')}
      ${input(fields,'calc-stock-amount','Amount in vial / syringe')}${select(fields,'calc-stock-unit','Stock amount unit',unitOptions,'mg')}${input(fields,'calc-stock-volume','Vial / syringe volume · mL')}
      </div>${resultBox(ordered?[['DOSE',fmt(ordered.amount),fields['calc-dose-unit']??'mg'],['DRAW VOLUME',fmt(ordered.volume),'mL']]:null)}${ordered?.limited?'<p class="dose-limit">Entered dose maximum applied.</p>':''}<p class="calculator-note"><b>Enter the ordered dose and the amount / volume printed on your vial. The result is how many mL to draw. For a per-kg order, enter patient weight above.</b></p></section>
    <section class="panel calculator"><h2>Fluid drip rate</h2><div class="calculator-fields">${input(fields,'drip-volume','Total volume · mL')}${input(fields,'drip-minutes','Infusion time · minutes')}${select(fields,'drip-factor','Tubing · gtt/mL',[['','Select tubing'],['10','10 · macrodrip'],['15','15 · macrodrip'],['20','20 · macrodrip'],['60','60 · microdrip']])}</div>
      ${resultBox(drip?[['PUMP RATE',fmt(drip.hourly),'mL/hr'],['GRAVITY · NEAREST DROP',String(drip.roundedDrops),'gtt/min']]:null)}<p class="calculator-note"><b>Enter how much fluid, how long it should run, and the drop size printed on the tubing. The result is the pump setting or drops to count each minute.</b></p></section>
    <section class="panel calculator"><h2>Medication infusion rate</h2><div class="calculator-fields">${input(fields,'infusion-dose','Ordered rate')}${select(fields,'infusion-unit','Rate unit',[['mcg/kg/min','mcg/kg/min'],['mcg/min','mcg/min'],['mg/min','mg/min'],['mg/hr','mg/hr'],['mcg/kg/hr','mcg/kg/hr']],'mcg/kg/min')}${input(fields,'infusion-amount','Medication amount in bag')}${select(fields,'infusion-stock-unit','Amount unit',[['mg','mg'],['mcg','mcg'],['g','g']],'mg')}${input(fields,'infusion-volume','Final bag volume · mL')}${select(fields,'infusion-factor','Tubing · gtt/mL (optional)',[['','Pump only'],['10','10'],['15','15'],['20','20'],['60','60']])}</div>
      ${resultBox(infusion?[['PUMP RATE',fmt(infusion.hourly),'mL/hr'],...(infusion.drops!==null?[['GRAVITY · NEAREST DROP',String(Math.round(infusion.drops)),'gtt/min']]:[])]:null)}<p class="calculator-note"><b>Enter the ordered drug rate and what is mixed in the bag. Use the final bag volume. The result tells you what to set the pump to.</b></p></section>
    <section class="panel calculator"><h2>Dilution</h2><div class="calculator-fields">${input(fields,'dilution-amount','Stock amount')}${select(fields,'dilution-stock-unit','Stock unit',[['mg','mg'],['mcg','mcg'],['g','g']],'mg')}${input(fields,'dilution-stock-volume','Stock volume · mL')}${input(fields,'dilution-target','Target concentration · per mL')}${select(fields,'dilution-target-unit','Target unit',[['mcg','mcg/mL'],['mg','mg/mL'],['g','g/mL']],'mcg')}${input(fields,'dilution-final-volume','Final total volume · mL')}</div>
      ${resultBox(dilution?[['DRAW STOCK',fmt(dilution.draw),'mL'],['ADD COMPATIBLE DILUENT',fmt(dilution.diluent),'mL']]:null,'Enter valid values; target must be lower than stock concentration.')}<p class="calculator-note"><b>Enter what is in the vial, the strength you need, and the final syringe or bag size. Draw the shown drug volume, then add the shown compatible diluent.</b></p></section>
  </div>`;
}

const sedationGroups=[['all','All doses'],['agitation','Agitation'],['intubated','After intubation'],['cardioversion','Cardioversion']];
const sedationGroup=id=>id.includes('restraint')?'agitation':id.includes('post-intubation')?'intubated':'cardioversion';
const sedationInstructions={
 'ket-restraint':['RASS +4 · IM once into a large muscle; use multiple sites as marked.'],
 'ket-post-intubation':['SBP <100 / hypotension risk. Normotensive: either T715 regimen.','Secure ETT; reassess before each dose.'],
 'versed-restraint':['Smaller / older adults: consider less. RASS +3 may use 5 mg.','Repeat only with online medical control.'],
 'versed-restraint-ped':['Repeat only with online medical control.'],
 'versed-post-intubation':['Give with fentanyl OR morphine. SBP >150 / hypertension risk.','Normotensive: either T715 regimen. Secure ETT.'],
 'versed-cardioversion':['Conscious, no altered mental status. Titrate until speech slurs.','Do not delay urgent cardioversion.'],
 'versed-cardioversion-narrow':['Conscious, no altered mental status. Titrate until speech slurs.','Do not delay urgent cardioversion.'],
 'versed-cardioversion-ped':['Conscious patient. Medical-control order required.']
};
function sedationRecipeCard(m,p,r,ri,fields){
 const concentration=p.concentration??stockConcentration(m);
 const unit=p.concentrationUnit??m.stock?.unit,priorKey=`prior-${p.id}-${ri}`;
 const result=calculateDose(r,{weightKg:patientKg(fields),idealKg:fields['ref-ideal'],age:fields['ref-age'],concentration,concentrationUnit:unit,prior:fields[priorKey],tableIndex:fields['ref-table']});
 const formula=r.kind==='weight'?`${range(r.low,r.high)} ${r.unit}/kg${r.ideal?' · ideal weight':''}`:`${range(r.low,r.high)} ${r.unit}`;
 const longValues=!result.error&&(range(result.low,result.high).length>5||(result.volumeLow!==null&&range(result.volumeLow,result.volumeHigh).length>5));
 return `<article class="sedation-dose-card" data-recipe="${p.id}-${ri}"><div class="sedation-dose-top"><h4>${esc(r.label)}</h4><div class="sedation-routes" aria-label="Route">${r.route.split(' / ').map(route=>`<span data-route="${route}">${route}</span>`).join('')}</div></div><div class="sedation-dose-rule"><span>${result.table?'Pediatric table · App J':esc(formula)}</span>${r.max!==undefined?`<b>MAX ${r.max} ${r.unit}</b>`:''}${r.totalMax!==undefined?`<b>MAX ${r.totalMax} ${r.unit} TOTAL</b>`:''}</div>${r.totalMax!==undefined?input(fields,priorKey,`Already given · ${r.unit} (0 if none)`,'Enter amount'):''}
 <div class="sedation-dose-output ${longValues?'long-values':''}" aria-live="polite">${result.error?`<p class="calculation-empty">${esc(result.error)}</p>`:`<div class="sedation-give"><span>DOSE</span><strong><span>${range(result.low,result.high)}</span> <small>${result.unit}</small></strong></div><div class="sedation-draw"><span>DRAW</span><strong><span>${result.volumeLow===null?'—':range(result.volumeLow,result.volumeHigh)}</span> <small>mL</small></strong><p>${result.volumeLow===null?'Confirm vial concentration.':`${fmt(concentration)} ${unit}/mL`}</p></div>${result.table?`<p class="sedation-dose-basis">${result.tableAge} · ${result.tableWeight} kg reference</p>`:''}${result.remaining!==null?`<p class="sedation-dose-remaining">${fmt(result.remaining)} ${result.unit} left before total maximum</p>`:''}`}</div></article>`;
}
export function sedationDosing(fields,source,icon){
 const group=sedationGroups.some(([id])=>id===fields['sedation-group'])?fields['sedation-group']:'all';
 const choices=[['ketamine',['ket-restraint','ket-post-intubation']],['midazolam',['versed-restraint','versed-restraint-ped','versed-post-intubation','versed-cardioversion','versed-cardioversion-narrow','versed-cardioversion-ped']]];
 return `<section class="sedation-quick" aria-labelledby="sedation-quick-title"><h2 id="sedation-quick-title">Sedation dosing</h2>${patientContext(fields,true,true).replace('<div class="reference-fields">','<h3 class="sedation-calculator-title">Patient calculator · age / weight</h3><div class="reference-fields">')}<div class="sedation-purpose" role="group" aria-label="Sedation indication">${sedationGroups.map(([id,label])=>`<button data-sedation-group="${id}" aria-pressed="${group===id}">${label}</button>`).join('')}</div><p class="sedation-monitor">Airway / suction ready · ECG, SpO₂, ETCO₂, BP · never leave unattended</p><div class="sedation-drugs">${choices.map(([id,ids])=>{const m=drugReference.find(d=>d.id===id),paths=m.pathways.filter(p=>ids.includes(p.id)&&(group==='all'||sedationGroup(p.id)===group));if(!paths.length)return '';return `<details class="drug-card ${id==='ketamine'?'teal':'blue'}" data-ref-open="sedation-${id}" data-clinical-open="sedation-${id}" ${fields['sedation-'+id+'-open']?'open':''}><summary><span class="drug-marker">${icon('syringe')}</span><span class="drug-name"><b>${id==='ketamine'?'Ketamine':'Versed / midazolam'}</b><small>${id==='ketamine'?(paths.some(p=>p.id==='ket-restraint')?'Agitation: height lookup · 50 mg/mL':'50 mg/mL stock'):'5 mg/mL stock'} · ${paths.length} dose guides</small></span><span class="expand-symbol">+</span></summary><div class="drug-content">${stockControl(m)}${paths.map(p=>`<section class="sedation-path" data-sedation-path="${esc(p.id)}"><div class="sedation-path-heading"><h3>${esc(p.title)}</h3><span class="sedation-age">${p.recipes[0].ageMin===16?'AGE 16+':p.recipes[0].ageMax===16?'UNDER 16':'INTUBATED'}</span></div>${p.id==='ket-restraint'?ketamineHeightChart(fields,source):`<div class="sedation-dose-grid">${p.recipes.map((recipe,i)=>sedationRecipeCard(m,p,recipe,i,fields)).join('')}</div>`}<div class="sedation-instructions">${sedationInstructions[p.id].map(n=>`<p>${esc(n)}</p>`).join('')}</div><details class="sedation-protocol-details"><summary>Protocol details · ${p.code}</summary><div class="path-notes">${p.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div>${source('FULL PROTOCOL · '+p.code,p.page)}</details></section>`).join('')}</div></details>`;}).join('')}</div></section>`;
}
export function bindSedationDosing(getState,save,render){document.addEventListener('click',e=>{const b=e.target.closest('[data-sedation-group]');if(!b||!sedationGroups.some(([id])=>id===b.dataset.sedationGroup))return;const fields=getState().fields;fields['sedation-group']=b.dataset.sedationGroup;fields['sedation-ketamine-open']=true;fields['sedation-midazolam-open']=true;save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-sedation-group="${b.dataset.sedationGroup}"]`)?.focus({preventScroll:true});});}
